m_hlThread = std::thread([this] {
    while (true) {
        int status = 0;
        int ret    = waitpid(m_hlPid, &status, 0);
        if (ret == -1) {
            g_logger->log(Hyprutils::CLI::LOG_ERR, "Couldn't waitpid for hyprland: {}", strerror(errno));
            break;
        }

        if (WIFEXITED(status))
            break;
    }
